import{_ as o,o as t,c as r,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Per-Subvolume IO Metrics in CephFS - Igor Golikov & Alex Markuze, IBM","description":"","frontmatter":{"title":"Per-Subvolume IO Metrics in CephFS - Igor Golikov & Alex Markuze, IBM","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["CephFS","Subvolume Metrics","Distributed Storage","Ceph","Observability"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Per-Subvolume_IO_Metrics_in_CephFS_-_Igor_Golikov_Alex_Markuze_IBM.md","filePath":"posts/2025/Per-Subvolume_IO_Metrics_in_CephFS_-_Igor_Golikov_Alex_Markuze_IBM.md","lastUpdated":1780459816000}'),s={name:"posts/2025/Per-Subvolume_IO_Metrics_in_CephFS_-_Igor_Golikov_Alex_Markuze_IBM.md"};function i(n,e,u,g,p,a){return t(),r("div",null,[...e[0]||(e[0]=[l('<h3 id="改进后的中文总结" tabindex="-1">改进后的中文总结 <a class="header-anchor" href="#改进后的中文总结" aria-label="Permalink to &quot;改进后的中文总结&quot;">​</a></h3><p>CephFS Subvolume Metrics 设计与未来观测性增强会议纪要</p><p>本次会议主要讨论了Ceph文件系统（CephFS）中Subvolume级别IO指标的引入及其未来观测性增强方案。以下是会议的关键点：</p><p><strong>会议概述</strong></p><ul><li><strong>主持人</strong>: Eager Goov (IBM CFS团队) 与 Alex Marcus (IBM SFS团队)</li><li><strong>核心主题</strong>: CephFS subvolume metrics 新特性及其未来观测性增强方案</li><li><strong>技术领域</strong>: 分布式存储，CephFS，指标收集，异常检测</li></ul><p><strong>关键讨论点</strong></p><ol><li><p><strong>Subvolume Metrics 特性介绍</strong></p><ul><li><strong>背景动机</strong>: 针对大规模Ceph集群中数千甚至数万个subvolumes，传统per-client监控无法定位热点路径性能瓶颈，需细粒度观测特定路径的IO活动状态。</li><li><strong>核心需求</strong>: Subvolume级别指标收集，高可扩展性，最小性能影响，MDS ranks间一致性，复用现有metrics基础设施，自动修剪非活跃metrics。</li><li><strong>指标设计</strong>: 数据类型包括IOPS/throughput/latency，采用30秒滑动窗口，平滑短期IO峰值，限制内存使用，自动清理非活跃路径指标。</li></ul></li><li><p><strong>系统架构</strong></p><ul><li><strong>数据流</strong>: Client记录单次IO操作，定期发送统计到关联MDS，MDS汇总数据到rank0 MDS，rank0 MDS维护全局滑动窗口聚合。</li><li><strong>关键技术点</strong>: Client通过MDS元数据响应识别subvolume路径，避免client端持久化存储，加权平均计算。</li></ul></li><li><p><strong>指标暴露</strong></p><ul><li>通过标准接口输出：Admin socket (<code>ceph daemon mds.&lt;id&gt; perf dump</code>), Prometheus exporter，未来将集成到<code>cephfs-top</code>工具。</li><li>JSON格式示例包含：Filesystem名称，Subvolume标识，读写IOPS/吞吐量/延迟。</li></ul></li><li><p><strong>未来工作计划</strong></p><ul><li><strong>短期增强</strong>: 增加metadata操作指标，支持自定义路径监控，用histogram替代平均值，Kernel client支持。</li><li><strong>长期方向</strong>: 异常检测系统，日志向量化分析，预测性洞察能力建设。</li></ul></li></ol><p><strong>Q&amp;A重点摘要</strong></p><ul><li><strong>客户端支持范围</strong>: 当前仅FUSE实现，NFS Ganesha理论上应兼容，Kernel client支持正在开发中。</li><li><strong>滑动窗口配置</strong>: 30秒为默认值，可通过配置参数调整。</li><li><strong>K8s集成</strong>: 目前缺乏PVC/PV与subvolume的直接关联，建议通过subvolume group命名实现间接关联。</li><li><strong>Prometheus输出</strong>: 当前设计采用服务端计算，讨论是否改为原生counter供客户端灵活计算。</li><li><strong>细粒度分析</strong>: 当前为subvolume聚合指标，未来可能增加per-client细分。</li></ul><p><strong>行动计划</strong></p><ul><li><strong>短期交付</strong>: 完成kernel client支持，增加subvolume监控配置灵活性，评估histogram实现方案。</li><li><strong>长期研究</strong>: 建立异常检测POC，开发日志-指标关联分析能力，优化时间序列预测模型。</li><li><strong>社区协作</strong>: 邀请用户提供生产环境指标数据，异常场景日志记录，使用场景反馈。</li></ul><p>本次会议在技术讨论和社区协作倡议中结束，与会者对新特性的实用价值和未来方向表示积极认可。</p>',12)])])}const m=o(s,[["render",i]]);export{c as __pageData,m as default};
